// Physical companion navigation, readable ship theft and cohesive foreground surfaces.
let companionRoutes=[],lastCompanionRoute='',shipEscaping=false,shipEscapeTime=0;
function companionStep(dt){if(!partner)return;const a=partner;a.vy ||=0;a.routeIndex ||=0;a.attack=Math.max(0,(a.attack||0)-dt);a.shootCd=Math.max(0,(a.shootCd||0)-dt);a.arrival=Math.max(0,(a.arrival||0)-dt);if(a.arrival)return;
 if(player.climb){const l=ladders.find(l=>Math.abs(l.x-player.x-17)<35&&player.y+86>=l.y-4&&player.y+86<=l.y+l.h+4);if(l){const dir=keys.down?1:-1,key=l.x+':'+l.y+':'+dir;if(lastCompanionRoute!==key){companionRoutes.push({...l,dir});lastCompanionRoute=key;}}}else lastCompanionRoute='';
 const r=companionRoutes[a.routeIndex],target=r?r.x-17:player.x-player.face*75;const shelf=!r&&solids.find(s=>Math.abs(s.y-player.y-86)<5&&player.x>=s.x&&player.x<s.x+s.w);const safeTarget=shelf?Math.max(shelf.x+20,Math.min(shelf.x+shelf.w-54,target)):target;const dx=safeTarget-a.x;const old=a.x;if(r&&Math.abs(dx)<5){a.x=r.x-17;a.climb=true;a.climbMoving=true;a.vy=0;a.y+=r.dir*130*dt;const landing=r.dir>0?r.y+r.h:r.y;if(r.dir>0&&a.y+86>=landing||r.dir<0&&a.y+86<=landing){a.y=landing-86;a.climb=false;a.ground=true;a.routeIndex++;}}else{a.climb=false;a.climbMoving=false;a.x+=Math.sign(dx)*Math.min(Math.abs(dx),200*dt);if(a.ground&&player.y<a.y-60&&!r){a.vy=-560;a.ground=false;}}
 if(!a.climb){const prev=a.y;a.vy+=1350*dt;a.y+=a.vy*dt;a.ground=false;for(const s of solids)if(a.x+34>s.x&&a.x<s.x+s.w&&prev+86<=s.y+3&&a.y+86>=s.y&&a.vy>=0){a.y=s.y-86;a.vy=0;a.ground=true;}}
 if(Math.abs(a.x-player.x)>650||a.y>Math.max(FLOOR,...solids.map(s=>s.y))+VH||Math.abs(a.y-player.y)>600){const landing=solids.filter(s=>player.x>=s.x&&player.x<s.x+s.w&&s.y>=player.y+75).sort((x,y)=>x.y-y.y)[0];if(landing){particles(a.x,a.y,'#a5c2df',8);a.x=player.x-player.face*65;a.y=landing.y-86;a.vy=0;a.climb=false;a.routeIndex=companionRoutes.length;}}
 a.vx=(a.x-old)/Math.max(dt,.001);if(Math.abs(a.vx)>5)a.face=Math.sign(a.vx);
}
function buildShipTheft(){chapters[3].length=2450;player.x=100;player.y=366;partner.x=35;partner.y=366;solids=[{x:0,y:452,w:700,h:100,kind:'wood'},{x:600,y:300,w:1600,h:22,kind:'wood'},{x:1740,y:220,w:360,h:22,kind:'wood'}];ladders=[{x:645,y:300,h:152},{x:1800,y:220,h:80}];covers=[];actors=[];objects=[{type:'bottle',x:190,y:425},{type:'bottle',x:370,y:425},{type:'rope',id:'bow-line',x:740,y:267},{type:'rope',id:'stern-line',x:1520,y:267},{type:'helm',x:1950,y:180}];shipEscaping=false;shipEscapeTime=0;talk('Nova','There’s our “taxi.” Two drinks on the dock, up the gangway, release the bow and stern lines, then take the helm on the quarterdeck.',7);}
function shipHUD(){if(chapter!==3||homeActive)return;const bottles=objects.filter(o=>o.type==='bottle'),lines=objects.filter(o=>o.type==='rope');const drink=bottles.find(o=>!o.done),line=lines.find(o=>!o.done);$('#chapter').textContent=shipEscaping?'Grand theft nautical':'Steal the ship';$('#objective').textContent=shipEscaping?'Moorings released · getting underway':drink?'1/4 · Have both drinks on the dock ('+bottles.filter(o=>o.done).length+'/2)':player.x<680?'2/4 · Board via the gangway ladder':line?'3/4 · Release '+(line.id==='bow-line'?'bow':'stern')+' mooring ('+lines.filter(o=>o.done).length+'/2)':'4/4 · Climb to the quarterdeck and take the helm';}
function shipInteraction(o){if(chapter!==3)return false;if(o.type==='helm'&&!objects.some(q=>['rope','bottle'].includes(q.type)&&!q.done)){shipEscaping=true;mode='escape';shipEscapeTime=0;for(const k in keys)keys[k]=false;talk('Sylvanas','“One drink,” she said. And now we are stealing a ship.',5);return true;}return false;}
function shipEscapeStep(dt){clock+=dt;shipEscapeTime+=dt;music(dt);if(shipEscapeTime>3){shipEscaping=false;mode='play';complete();}}
function terrainFrame(f,x,y,w,h){const im=assets.terrain;if(!im)return false;const sw=im.width/3,sh=im.height/2,c=SPRITE_BOUNDS.terrain?.frames[f];if(c)ctx.drawImage(im,c.x,c.y,c.w,c.h,x-camera,y,w,h);else ctx.drawImage(im,(f%3)*sw,Math.floor(f/3)*sh,sw,sh,x-camera,y,w,h);return true;}
const priorPlatform=platform;platform=function(s){if(homeActive)return priorPlatform(s);if(!assets.terrain)return priorPlatform(s);const f=s.kind==='metal'?2:s.kind==='stone'?1:0;const stride=s.h<30?170:200;ctx.save();ctx.beginPath();ctx.rect(s.x-camera,s.y,s.w,s.h<30?95:s.h);ctx.clip();for(let x=s.x;x<s.x+s.w;x+=stride)terrainFrame(f,x,s.y-3,stride,100);ctx.restore();if(s.h>=50){rect(s.x-camera,s.y+60,s.w,Math.max(0,s.h-60),s.kind==='metal'?'#162632':s.kind==='stone'?'#30372e':'#362820');}path([[s.x-camera,s.y],[s.x+s.w-camera,s.y]],s.kind==='metal'?'#9ab2bb':s.kind==='stone'?'#9aab7b':'#d0ad73',2);};
function drawShipBody(){if(assets.ship)ctx.drawImage(assets.ship,570-camera,20,1700,475);}
function drawShipTheft(){for(const o of objects){const x=o.x-camera;if(o.type==='bottle'){if(!o.done){rect(x-8,430,16,22,'#509a70');rect(x-4,423,8,7,'#c4a677');ctx.strokeStyle='#f2d898';ctx.lineWidth=2;ctx.strokeRect(x-12,420,24,34);}}else if(o.type==='rope'){terrainFrame(4,o.x-35,235,70,65);rect(x-120,392,20,100,'#60412b');rect(x-124,392,28,7,'#bd9b6d');path([[x-117,405],[x-103,405]],'#d3b585',5);if(!o.done){path([[x,267],[x-110,405]],'#d3b585',5);for(let i=0;i<4;i++)path([[x-i*5-10,280+i*8],[x+7-i*5,285+i*8]],'#8c7658',2);}else{path([[x,267],[x-15,296],[x+18,296]],'#9c8058',3);}}else if(o.type==='helm')terrainFrame(5,o.x-48,135,96,85);}if(shipEscaping){const progress=Math.min(1,shipEscapeTime/3);ctx.fillStyle='#192e4333';ctx.fillRect(0,0,VW,VH);for(let i=0;i<5;i++)path([[640-camera+i*70-progress*150,460],[690-camera+i*70-progress*150,460]],'#96b6c8',2);}}
const oldRefineDetails=drawMissionDetails;drawMissionDetails=function(){if(chapter===3){drawShipTheft();return;}oldRefineDetails();if(chapter===5){const winch=objects.find(o=>o.prop==='winch');if(winch)terrainFrame(3,winch.x-55,110,110,80);}};
const refineStart=start;start=function(n){refineStart(n);companionRoutes=[];lastCompanionRoute='';shipEscaping=false;if(n===3)buildShipTheft();if(n===0)groundOpeningEnemies();};window.RumIsland.start=start;
function groundOpeningEnemies(){for(const e of actors){const candidates=solids.filter(p=>e.origin>=p.x+3&&e.origin+e.w<=p.x+p.w-3);const shelf=candidates.sort((a,b)=>Math.abs(a.y-e.y-e.h)-Math.abs(b.y-e.y-e.h))[0];if(shelf){e.y=shelf.y-e.h;e.support=shelf;}}}
stepSummons=function(dt){for(const s of summons){s.life-=dt;s.cd-=dt;s.attack=Math.max(0,(s.attack||0)-dt);if(!s.support){s.support=solids.filter(p=>player.x+17>=p.x&&player.x+17<p.x+p.w&&p.y>=s.y-4).sort((a,b)=>a.y-b.y)[0];}if(!s.support){s.vx=0;continue;}const shelf=s.support;s.y=shelf.y;const target=actors.find(e=>!e.dead&&!e.inactive&&Math.abs(e.y+e.h-shelf.y)<5&&e.x>=shelf.x&&e.x+e.w<=shelf.x+shelf.w&&Math.abs(e.x-s.x)<350);const sameLevel=Math.abs(player.y+86-shelf.y)<5&&!player.climb;const goal=target?target.x-55*(Math.sign(target.x-s.x)||1):sameLevel?player.x-player.face*80:s.x;const safe=Math.max(shelf.x+25,Math.min(shelf.x+shelf.w-25,goal)),old=s.x;s.x=Math.max(shelf.x+25,Math.min(shelf.x+shelf.w-25,s.x+Math.sign(safe-s.x)*Math.min(Math.abs(safe-s.x),180*dt)));s.vx=(s.x-old)/Math.max(.001,dt);if(Math.abs(s.vx)>3)s.face=Math.sign(s.vx);if(target&&Math.abs(target.x-s.x)<90&&s.cd<=0){s.face=Math.sign(target.x-s.x)||1;s.attack=.4;s.cd=.85;damage(target,2);particles(target.x+17,target.y+30,'#ba81ef',10);effect('magic');}}summons=summons.filter(s=>s.life>0);};
drawSummons=function(){const im=assets.summonMotion;if(!im)return;for(const s of summons){const row=s.attack>0?1:0,f=s.attack>0?Math.min(3,Math.floor((.4-s.attack)/.1)):Math.abs(s.vx||0)>3?Math.floor(clock*7)%4:0;const c=SPRITE_BOUNDS.summonMotion?.frames[row*4+f];if(!c)continue;const base=SPRITE_BOUNDS.summonMotion.base,h=c.h*100/base,w=c.w*100/base;ctx.save();ctx.translate(s.x-camera,s.y);ctx.scale(s.face||1,1);ctx.globalAlpha=Math.min(.85,s.life);ctx.drawImage(im,c.x,c.y,c.w,c.h,-w/2,-h,w,h);ctx.restore();}};

const barDetails=drawMissionDetails;drawMissionDetails=function(){barDetails();if(chapter!==2)return;const x=2080-camera,ready=actors.every(e=>e.dead);rect(x-45,FLOOR-145,90,145,'#1b1512');rect(x-39,FLOOR-138,78,138,'#58402b');rect(x-33,FLOOR-131,29,115,'#2b211b');rect(x+4,FLOOR-131,29,115,'#2b211b');rect(x+24,FLOOR-70,5,5,'#dfbb75');rect(x-52,FLOOR-170,104,22,'#231a13');ctx.fillStyle=ready?'#a4edb0':'#dfbb75';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText('HARBOR EXIT →',x,FLOOR-155);if(ready){ctx.strokeStyle='#a4edb0';ctx.lineWidth=3;ctx.strokeRect(x-40,FLOOR-140,80,140);}};
